<?php
require __DIR__.'/../app/bootstrap.php';require_admin();
$testId=filter_input(INPUT_GET,'test_id',FILTER_VALIDATE_INT);if(!$testId)redirect('admin.php');
$s=$pdo->prepare("SELECT t.*,tp.id topic_id,tp.name topic_name,tp.subject_id FROM tests t JOIN topics tp ON tp.id=t.topic_id WHERE t.id=?");$s->execute([$testId]);$test=$s->fetch();if(!$test)exit('Test niet gevonden.');require_subject_management((int)$test['subject_id']);
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['delete_id'])){$s=$pdo->prepare("DELETE FROM questions WHERE id=? AND test_id=?");$s->execute([(int)$_POST['delete_id'],$testId]);redirect('questions.php?test_id='.$testId);}
$s=$pdo->prepare("SELECT q.id,q.question_text,q.question_type,q.sort_order,COUNT(o.id) option_count,SUM(o.is_correct) correct_count,(SELECT COUNT(*) FROM open_question_answers oa WHERE oa.question_id=q.id) open_answer_count FROM questions q LEFT JOIN question_options o ON o.question_id=q.id WHERE q.test_id=? GROUP BY q.id ORDER BY q.sort_order,q.id");$s->execute([$testId]);$questions=$s->fetchAll();
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vragen</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><a href="subject_manage.php?id=<?=(int)$test['subject_id']?>">&larr; Terug naar <?=e($test['topic_name'])?></a><div class="d-flex justify-content-between align-items-center mt-3 mb-3"><div><h1><?=e($test['title'])?></h1><p class="text-secondary mb-0">Vragen beheren</p></div><a class="btn btn-primary" href="question_edit.php?test_id=<?=$testId?>">Nieuwe vraag</a></div><div class="card shadow-sm"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>#</th><th>Vraag</th><th>Type</th><th>Antwoorden</th><th></th></tr></thead><tbody><?php foreach($questions as $i=>$q):?><tr><td><?=$i+1?></td><td><?=e($q['question_text'])?></td><td><?= $q['question_type']==='open'?'Open':'Meerkeuze'?></td><td><?= $q['question_type']==='open' ? $q['open_answer_count'].' goed' : $q['option_count'].' / juiste: '.($q['correct_count']??0) ?></td><td><a class="btn btn-sm btn-outline-primary" href="question_edit.php?id=<?=$q['id']?>&test_id=<?=$testId?>">Bewerken</a> <form class="d-inline" method="post" data-confirm="Weet u zeker dat u deze vraag wilt verwijderen?"><input type="hidden" name="delete_id" value="<?=$q['id']?>"><button class="btn btn-sm btn-danger">Verwijderen</button></form></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>
